using System.Net;
using System.Net.Http.Json;
using PaymentAuthorization.Domain;
using Infrastructure = PaymentAuthorization.Infrastructure;

namespace PaymentAuthorization.IntegrationTest.PaymentGateway;

/// <summary>
/// Verifies the wire contract between HttpPaymentGateway and the provider's REST API:
/// what we send, and how we interpret every response shape the provider can send back.
/// </summary>
public sealed class HttpPaymentGatewayTests
{
    private static readonly Money Amount = new(42.50m, "eur");

    [Fact]
    public async Task Sends_the_reference_and_amount_as_the_provider_expects()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.OK, """{"status":"approved"}""");
        var sut = CreateSut(handler);

        await sut.AuthorizeAsync("ORD-7", Amount, CancellationToken.None);

        Assert.Equal(HttpMethod.Post, handler.Request!.Method);
        Assert.Equal("/v1/authorizations", handler.Request.RequestUri!.AbsolutePath);

        var sent = await handler.Request.Content!.ReadFromJsonAsync<Dictionary<string, object>>();
        Assert.Equal("ORD-7", sent!["reference"].ToString());
        Assert.Equal(42.50m, decimal.Parse(sent["amount"].ToString()!));
        Assert.Equal("EUR", sent["currency"].ToString());
    }

    [Fact]
    public async Task Approved_status_in_the_body_is_read_as_an_approved_outcome()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.OK, """{"status":"approved"}""");
        var sut = CreateSut(handler);

        var outcome = await sut.AuthorizeAsync("ORD-7", Amount, CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Approved, outcome);
    }

    [Fact]
    public async Task Declined_status_in_the_body_is_read_as_a_declined_outcome()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.OK, """{"status":"declined"}""");
        var sut = CreateSut(handler);

        var outcome = await sut.AuthorizeAsync("ORD-7", Amount, CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unrecognised_status_in_the_body_is_treated_as_declined()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.OK, """{"status":"pending_review"}""");
        var sut = CreateSut(handler);

        var outcome = await sut.AuthorizeAsync("ORD-7", Amount, CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task A_402_response_means_the_provider_refused_the_payment_outright()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.PaymentRequired, responseBody: null);
        var sut = CreateSut(handler);

        var outcome = await sut.AuthorizeAsync("ORD-7", Amount, CancellationToken.None);

        Assert.Equal(AuthorizationOutcome.Declined, outcome);
    }

    [Fact]
    public async Task An_unexpected_error_status_from_the_provider_is_not_swallowed_as_a_decline()
    {
        var handler = new StubHttpMessageHandler(HttpStatusCode.InternalServerError, responseBody: null);
        var sut = CreateSut(handler);

        await Assert.ThrowsAsync<HttpRequestException>(
            () => sut.AuthorizeAsync("ORD-7", Amount, CancellationToken.None));
    }

    private static Infrastructure.HttpPaymentGateway CreateSut(HttpMessageHandler handler) =>
        new(new HttpClient(handler) { BaseAddress = new Uri("https://provider.example.test") });
}
